// CommandAdopter splits files by running an external command the user allowed.
type CommandAdopter struct {
	Argv []string
	Dir  string
}

// ParseSpans reads one JSON document of the form {"spans":[...]} and returns its spans.
// Unknown fields, trailing data, and an empty or missing spans list are errors.
// The spans are not validated here; CheckSpans does that.
func ParseSpans(r io.Reader) ([]Span, error) {
	dec := json.NewDecoder(r)
	dec.DisallowUnknownFields()
	var doc struct {
		Spans []Span `json:"spans"`
	}
	if err := dec.Decode(&doc); err != nil {
		return nil, fmt.Errorf("decoding spans: %w", err)
	}
	if err := dec.Decode(&struct{}{}); err != io.EOF {
		return nil, errors.New("trailing data after spans document")
	}
	if len(doc.Spans) == 0 {
		return nil, errors.New("adopter returned no spans")
	}
	return doc.Spans, nil
}

// Split runs the command with path appended to its arguments and parses the
// spans it prints on stdout. The command reads the file itself, so src is not
// passed to it.
func (c CommandAdopter) Split(path string, src []byte) ([]Span, error) {
	if len(c.Argv) == 0 {
		return nil, errors.New("command adopter: empty command line")
	}
	ctx, cancel := context.WithTimeout(context.Background(), commandTimeout)
	defer cancel()
	args := append(append([]string{}, c.Argv[1:]...), path)
	cmd := exec.CommandContext(ctx, c.Argv[0], args...)
	cmd.Dir = c.Dir
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			msg := strings.SplitN(stderr.String(), "\n", 2)[0]
			return nil, fmt.Errorf("command adopter %s: exit status %d: %s", c.Argv[0], exitErr.ExitCode(), msg)
		}
		return nil, fmt.Errorf("command adopter %s: %w", c.Argv[0], err)
	}
	if stdout.Len() > maxCommandOutput {
		return nil, fmt.Errorf("command adopter %s: stdout exceeds %d bytes", c.Argv[0], maxCommandOutput)
	}
	spans, err := ParseSpans(&stdout)
	if err != nil {
		return nil, fmt.Errorf("command adopter %s: %w", c.Argv[0], err)
	}
	return spans, nil
}

// String returns the command line, Argv joined by single spaces.
func (c CommandAdopter) String() string {
	return strings.Join(c.Argv, " ")
}

func TestParseSpans(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		wantErr bool
		wantLen int
	}{
		{"valid", `{"spans":[{"kind":"header","text":"x"},{"kind":"unit","text":"f()","action":"setFunction","kwargs":{"name":"f"}}]}`, false, 2},
		{"unknown field", `{"spans":[{"kind":"header","text":"x"}],"extra":1}`, true, 0},
		{"trailing data", `{"spans":[{"kind":"header","text":"x"}]} {}`, true, 0},
		{"empty spans", `{"spans":[]}`, true, 0},
		{"missing spans", `{}`, true, 0},
		{"invalid json", `{"spans":`, true, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			spans, err := ParseSpans(strings.NewReader(tt.input))
			if (err != nil) != tt.wantErr {
				t.Fatalf("ParseSpans error = %v, wantErr %v", err, tt.wantErr)
			}
			if len(spans) != tt.wantLen {
				t.Fatalf("got %d spans, want %d", len(spans), tt.wantLen)
			}
		})
	}
}

func TestCommandAdopterSplit(t *testing.T) {
	dir := t.TempDir()
	file := filepath.Join(dir, "input.txt")
	if err := os.WriteFile(file, []byte("x"), 0o644); err != nil {
		t.Fatal(err)
	}
	tests := []struct {
		name    string
		script  string
		wantErr string
	}{
		{
			name:   "success",
			script: `printf '{"spans":[{"kind":"residual","text":"%s"}]}' "$1"`,
		},
		{
			name:    "non-zero exit",
			script:  `echo boom >&2; exit 3`,
			wantErr: "exit status 3: boom",
		},
		{
			name:    "malformed stdout",
			script:  `echo 'not json'`,
			wantErr: "decoding spans",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			script := filepath.Join(dir, tt.name+".sh")
			if err := os.WriteFile(script, []byte(tt.script+"\n"), 0o644); err != nil {
				t.Fatal(err)
			}
			c := CommandAdopter{Argv: []string{"sh", script}}
			spans, err := c.Split(file, nil)
			if tt.wantErr != "" {
				if err == nil || !strings.Contains(err.Error(), tt.wantErr) {
					t.Fatalf("Split error = %v, want it to contain %q", err, tt.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("Split: %v", err)
			}
			if len(spans) != 1 || spans[0].Text != file {
				t.Fatalf("got spans %+v, want one span with the path %q", spans, file)
			}
		})
	}
	if _, err := (CommandAdopter{}).Split(file, nil); err == nil {
		t.Fatal("empty Argv: want error")
	}
}

func TestCommandString(t *testing.T) {
	tests := []struct {
		name string
		argv []string
		want string
	}{
		{"single", []string{"adopt"}, "adopt"},
		{"multiple", []string{"sh", "script", "-v"}, "sh script -v"},
		{"empty", nil, ""},
	}
	for _, tt := range tests {
		c := CommandAdopter{Argv: tt.argv}
		if got := c.String(); got != tt.want {
			t.Errorf("%s: String() = %q, want %q", tt.name, got, tt.want)
		}
	}
}

func TestCommandAdopterRunsInDir(t *testing.T) {
	work := t.TempDir()
	if err := os.WriteFile(filepath.Join(work, "x.txt"), []byte("x"), 0o644); err != nil {
		t.Fatal(err)
	}
	scripts := t.TempDir()
	script := filepath.Join(scripts, "pwd.sh")
	body := `printf '{"spans":[{"kind":"residual","text":"%s"}]}' "$(pwd)"` + "\n"
	if err := os.WriteFile(script, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	c := CommandAdopter{Argv: []string{"sh", script}, Dir: work}
	spans, err := c.Split("x.txt", nil)
	if err != nil {
		t.Fatalf("Split: %v", err)
	}
	if len(spans) != 1 || !strings.HasSuffix(spans[0].Text, filepath.Base(work)) {
		t.Fatalf("got spans %+v, want text ending in %q", spans, filepath.Base(work))
	}
}

